begin;
-- Sprint 42. Valores ambientais são registros gerenciais; fatores e certificações nunca são inferidos.
create table sustainability_environmental_compliances(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenancy.tenants(id),farm_id uuid not null,producer_name varchar(200) not null,total_area numeric(18,6) not null check(total_area>0),productive_area numeric(18,6) not null check(productive_area>=0 and productive_area<=total_area),preservation_area numeric(18,6) not null default 0 check(preservation_area>=0),app_area numeric(18,6) not null default 0 check(app_area>=0),legal_reserve_area numeric(18,6) not null default 0 check(legal_reserve_area>=0),car_number varchar(80),car_status varchar(30) not null default 'NOT_INFORMED',environmental_license varchar(120),license_valid_until date,issuing_agency varchar(160),georeferenced boolean not null default false,status varchar(30) not null check(status in('REGULAR','UNDER_REVIEW','PENDING','EXPIRED','BLOCKED','NOT_INFORMED','REJECTED')),risk varchar(20) not null check(risk in('LOW','MEDIUM','HIGH','CRITICAL','NOT_ASSESSED')),notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null,updated_by uuid not null,deleted_at timestamptz,unique(tenant_id,id),unique(tenant_id,farm_id),foreign key(tenant_id,farm_id) references geo.farms(tenant_id,id),check(car_number is null or car_number~'^[A-Za-z0-9.\/-]{5,80}$'));
create table sustainability_environmental_documents(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenancy.tenants(id),compliance_id uuid,farm_id uuid,type varchar(40) not null check(type in('CAR','ENVIRONMENTAL_LICENSE','USE_AUTHORIZATION','ENVIRONMENTAL_CERTIFICATE','TECHNICAL_REPORT','GEOREFERENCING','PHOTOGRAPHIC_EVIDENCE','AUDIT_DOCUMENT','ORGANIC_CERTIFICATION','SOCIOENVIRONMENTAL_CERTIFICATION','SUSTAINABLE_ORIGIN','OTHER')),document_id uuid,title varchar(200) not null,issued_on date,valid_until date,mandatory boolean not null default false,status varchar(20) not null check(status in('PENDING','APPROVED','REJECTED','EXPIRED')),decision_reason text,approved_at timestamptz,approved_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null,updated_by uuid not null,deleted_at timestamptz,unique(tenant_id,id),foreign key(tenant_id,compliance_id) references sustainability_environmental_compliances(tenant_id,id),foreign key(tenant_id,farm_id) references geo.farms(tenant_id,id),check(valid_until is null or issued_on is null or valid_until>=issued_on),check(status<>'REJECTED' or nullif(trim(decision_reason),'') is not null),check(status<>'APPROVED' or (approved_at is not null and approved_by is not null)));
create table sustainability_esg_indicators(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenancy.tenants(id),name varchar(180) not null,category varchar(30) not null,description text,unit varchar(30) not null,target numeric(20,6),current_value numeric(20,6),periodicity varchar(20) not null,data_source varchar(200) not null,responsible_id uuid,status varchar(20) not null check(status in('ACTIVE','ATTENTION','CRITICAL','INACTIVE','PENDING_DATA')),attention_limit numeric(20,6),critical_limit numeric(20,6),notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null,updated_by uuid not null,deleted_at timestamptz,unique(tenant_id,id),check(nullif(trim(data_source),'') is not null),check(unit<>'PERCENT' or (target between 0 and 100 and current_value between 0 and 100)));
create table sustainability_esg_measurements(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,indicator_id uuid not null,measured_on date not null,value numeric(20,6) not null,source varchar(200) not null,evidence_document_id uuid,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null,updated_by uuid not null,foreign key(tenant_id,indicator_id) references sustainability_esg_indicators(tenant_id,id));
create table sustainability_emission_inventories(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenancy.tenants(id),farm_id uuid,period_start date not null,period_end date not null,source varchar(180) not null,category varchar(30) not null,quantity numeric(20,6) not null check(quantity>0),unit varchar(30) not null,emission_factor numeric(20,9) check(emission_factor>0),estimated_emission numeric(20,6),scope varchar(20),methodology text,calculation_memory jsonb not null default '{}',status varchar(20) not null check(status in('CALCULATED','PENDING_FACTOR','CANCELLED')),notes text,evidence_document_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null,updated_by uuid not null,deleted_at timestamptz,unique(tenant_id,id),foreign key(tenant_id,farm_id) references geo.farms(tenant_id,id),check(period_end>=period_start),check((emission_factor is null and estimated_emission is null and status='PENDING_FACTOR') or (emission_factor is not null and estimated_emission=round(quantity*emission_factor,6))));
create table sustainability_resource_usages(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenancy.tenants(id),farm_id uuid,period_start date not null,period_end date not null,resource_type varchar(20) not null check(resource_type in('WATER','ENERGY','FUEL','INPUT')),quantity numeric(20,6) not null check(quantity>=0),unit varchar(30) not null,cost numeric(20,2) check(cost>=0),data_origin varchar(200) not null,evidence_document_id uuid,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null,updated_by uuid not null,deleted_at timestamptz,unique(tenant_id,id),foreign key(tenant_id,farm_id) references geo.farms(tenant_id,id),check(period_end>=period_start));
create table sustainability_waste_records(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenancy.tenants(id),farm_id uuid,recorded_on date not null,type varchar(80) not null,quantity numeric(20,6) not null check(quantity>=0),unit varchar(30) not null,destination varchar(200) not null,manifest_document_id uuid,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null,updated_by uuid not null,deleted_at timestamptz,unique(tenant_id,id),foreign key(tenant_id,farm_id) references geo.farms(tenant_id,id));
create table sustainability_supplier_assessments(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenancy.tenants(id),supplier_id uuid not null,category varchar(80) not null,environmental_risk varchar(20) not null,social_risk varchar(20) not null,operational_risk varchar(20) not null,status varchar(20) not null check(status in('APPROVED','UNDER_REVIEW','PENDING','REJECTED','BLOCKED','EXPIRED')),valid_until date,nonconformity_history text,certifications text,reason text,approved_at timestamptz,approved_by uuid,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null,updated_by uuid not null,deleted_at timestamptz,unique(tenant_id,id),foreign key(tenant_id,supplier_id) references procurement.suppliers(tenant_id,id),check(status<>'REJECTED' or nullif(trim(reason),'') is not null),check(status<>'APPROVED' or (approved_at is not null and approved_by is not null)));
create table sustainability_lot_traceability(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenancy.tenants(id),lot_id uuid not null,farm_id uuid,producer_name varchar(200),status varchar(35) not null check(status in('COMPLIANT','UNDER_REVIEW','PENDING','BLOCKED','REJECTED','RELEASED_WITH_RESERVATION')),justification text,production_reference uuid,quality_reference uuid,export_reference uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null,updated_by uuid not null,deleted_at timestamptz,unique(tenant_id,id),unique(tenant_id,lot_id),foreign key(lot_id) references storage.lots(id),foreign key(tenant_id,farm_id) references geo.farms(tenant_id,id),check(status<>'COMPLIANT' or farm_id is not null),check(status<>'RELEASED_WITH_RESERVATION' or nullif(trim(justification),'') is not null));
create table sustainability_carbon_projects(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenancy.tenants(id),farm_id uuid,name varchar(200) not null,type varchar(50) not null,period_start date not null,period_end date not null,area numeric(18,6) check(area>0),methodology text,estimated_carbon numeric(20,6),certified boolean not null default false,certification_document_id uuid,status varchar(25) not null check(status in('DRAFT','UNDER_REVIEW','ACTIVE','INTERNALLY_APPROVED','CERTIFIED','COMPLETED','CANCELLED')),responsible_id uuid,cancellation_reason text,notes text,approved_at timestamptz,approved_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null,updated_by uuid not null,deleted_at timestamptz,unique(tenant_id,id),foreign key(tenant_id,farm_id) references geo.farms(tenant_id,id),check(period_end>=period_start),check(estimated_carbon is null or nullif(trim(methodology),'') is not null),check(not certified or certification_document_id is not null),check(status<>'CANCELLED' or nullif(trim(cancellation_reason),'') is not null));
create table sustainability_audits(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenancy.tenants(id),type varchar(20) not null check(type in('INTERNAL','EXTERNAL')),scope text not null,responsible_id uuid,due_on date,status varchar(25) not null check(status in('PLANNED','IN_PROGRESS','COMPLETED','PENDING','REJECTED','CANCELLED')),cancellation_reason text,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null,updated_by uuid not null,deleted_at timestamptz,unique(tenant_id,id),check(status<>'CANCELLED' or nullif(trim(cancellation_reason),'') is not null));
create table sustainability_audit_items(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,audit_id uuid not null,description text not null,compliant boolean,nonconformity text,responsible_id uuid,due_on date,evidence_document_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null,updated_by uuid not null,foreign key(tenant_id,audit_id) references sustainability_audits(tenant_id,id),check(nonconformity is null or responsible_id is not null));
create table sustainability_action_plans(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenancy.tenants(id),origin varchar(100) not null,category varchar(60) not null,description text not null,responsible_id uuid,due_on date not null,priority varchar(15) not null check(priority in('LOW','MEDIUM','HIGH','CRITICAL')),status varchar(30) not null check(status in('OPEN','IN_PROGRESS','AWAITING_EVIDENCE','COMPLETED','OVERDUE','CANCELLED')),evidence_document_id uuid,result text,cancellation_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null,updated_by uuid not null,deleted_at timestamptz,unique(tenant_id,id),check(priority<>'CRITICAL' or responsible_id is not null),check(status<>'COMPLETED' or nullif(trim(result),'') is not null),check(status<>'CANCELLED' or nullif(trim(cancellation_reason),'') is not null));
create table sustainability_alerts(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenancy.tenants(id),type varchar(50) not null,severity varchar(20) not null check(severity in('INFO','ATTENTION','HIGH','CRITICAL')),entity_type varchar(50),entity_id uuid,message text not null,status varchar(20) not null check(status in('OPEN','ACKNOWLEDGED','RESOLVED','CANCELLED')),due_at timestamptz,resolved_at timestamptz,resolved_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,unique(tenant_id,id));
create table sustainability_report_exports(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenancy.tenants(id),report varchar(60) not null,filters jsonb not null default '{}',row_count integer not null check(row_count>=0),created_at timestamptz not null default now(),created_by uuid not null);
create index ix_sus_compliance_status on sustainability_environmental_compliances(tenant_id,status,risk,farm_id) where deleted_at is null; create index ix_sus_documents_due on sustainability_environmental_documents(tenant_id,status,valid_until,farm_id) where deleted_at is null; create index ix_sus_indicators on sustainability_esg_indicators(tenant_id,status,category) where deleted_at is null; create index ix_sus_measurements on sustainability_esg_measurements(tenant_id,indicator_id,measured_on desc); create index ix_sus_emissions on sustainability_emission_inventories(tenant_id,status,category,period_start) where deleted_at is null; create index ix_sus_resources on sustainability_resource_usages(tenant_id,resource_type,period_start,farm_id) where deleted_at is null; create index ix_sus_waste on sustainability_waste_records(tenant_id,recorded_on,farm_id) where deleted_at is null; create index ix_sus_supplier on sustainability_supplier_assessments(tenant_id,status,environmental_risk,supplier_id) where deleted_at is null; create index ix_sus_lot on sustainability_lot_traceability(tenant_id,status,lot_id,farm_id) where deleted_at is null; create index ix_sus_carbon on sustainability_carbon_projects(tenant_id,status,period_start,farm_id) where deleted_at is null; create index ix_sus_audits on sustainability_audits(tenant_id,status,due_on) where deleted_at is null; create index ix_sus_actions on sustainability_action_plans(tenant_id,status,priority,due_on) where deleted_at is null; create index ix_sus_alerts on sustainability_alerts(tenant_id,status,severity,created_at desc);
do $$ declare tab text; begin foreach tab in array array['sustainability_environmental_compliances','sustainability_environmental_documents','sustainability_esg_indicators','sustainability_esg_measurements','sustainability_emission_inventories','sustainability_resource_usages','sustainability_waste_records','sustainability_supplier_assessments','sustainability_lot_traceability','sustainability_carbon_projects','sustainability_audits','sustainability_audit_items','sustainability_action_plans','sustainability_alerts','sustainability_report_exports'] loop execute format('alter table %I enable row level security',tab); execute format('alter table %I force row level security',tab); execute format('create policy %I on %I using (tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid) with check (tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',tab||'_tenant',tab); end loop; end $$;
insert into identity.permissions(code,module,description) values('sustainability.read','Sustentabilidade e ESG','Consultar governança socioambiental.'),('sustainability.write','Sustentabilidade e ESG','Registrar dados socioambientais.'),('sustainability.approve','Sustentabilidade e ESG','Aprovar, bloquear e liberar registros ESG.'),('sustainability.reports','Sustentabilidade e ESG','Exportar relatórios ESG.') on conflict(code) do update set module=excluded.module,description=excluded.description;
insert into platform.schema_versions(version,description,installed_at) values('4.2.0','Sprint 42 - Sustentabilidade e ESG',now()) on conflict(version) do nothing;
commit;
